'use strict';

const fs = require('fs');
const input = fs.readFileSync(0, 'utf8').trim().split(/\s+/).map(Number);

let idx = 0;
const n = input[idx++];
const graph = Array.from({ length: n }, () => []);

for (let i = 0; i < n - 1; i++) {
  const a = input[idx++] - 1;
  const b = input[idx++] - 1;
  graph[a].push(b);
  graph[b].push(a);
}

function bfs(start, withParent = false) {
  const dist = new Int32Array(n);
  dist.fill(-1);
  const parent = withParent ? new Int32Array(n) : null;
  const queue = new Int32Array(n);
  let head = 0;
  let tail = 0;
  let farthest = start;

  queue[tail++] = start;
  dist[start] = 0;

  while (head < tail) {
    const v = queue[head++];
    if (dist[v] > dist[farthest]) farthest = v;

    for (const u of graph[v]) {
      if (dist[u] !== -1) continue;
      dist[u] = dist[v] + 1;
      if (parent) parent[u] = v;
      queue[tail++] = u;
    }
  }

  return { dist, parent, farthest };
}

const first = bfs(0);
const start = first.farthest;
const second = bfs(start, true);
const end = second.farthest;
const diameter = second.dist[end];

const path = [];
for (let v = end; ; v = second.parent[v]) {
  path.push(v);
  if (v === start) break;
}

const stackNode = new Int32Array(n);
const stackParent = new Int32Array(n);
const stackDepth = new Int32Array(n);

function countAtDepth(startNode, blockedNode, targetDepth) {
  let top = 0;
  let count = 0;

  stackNode[top] = startNode;
  stackParent[top] = blockedNode;
  stackDepth[top++] = 0;

  while (top > 0) {
    top--;
    const v = stackNode[top];
    const parent = stackParent[top];
    const depth = stackDepth[top];

    if (depth === targetDepth) {
      count++;
      continue;
    }

    for (const u of graph[v]) {
      if (u === parent) continue;
      stackNode[top] = u;
      stackParent[top] = v;
      stackDepth[top++] = depth + 1;
    }
  }

  return count;
}

let ways = 0;

if (diameter % 2 === 0) {
  const center = path[diameter / 2];
  const targetDepth = diameter / 2;
  const branchCounts = [];

  for (const neighbor of graph[center]) {
    branchCounts.push(countAtDepth(neighbor, center, targetDepth - 1));
  }

  let seen = 0;
  for (const count of branchCounts) {
    ways += seen * count;
    seen += count;
  }
} else {
  const leftCenter = path[Math.floor(diameter / 2)];
  const rightCenter = path[Math.floor(diameter / 2) + 1];
  const depth = Math.floor(diameter / 2);

  ways =
    countAtDepth(leftCenter, rightCenter, depth) *
    countAtDepth(rightCenter, leftCenter, depth);
}

console.log(`${diameter + 1}\n${ways}`);
